INSERT INTO Active (ActiveID, Description, Content, AwardContent, HasKey, EndDate, IsOnly, StartDate, Title, Type, ActiveType, ActionTimeContent, IsAdvance, GoodsExchangeTypes, GoodsExchangeNum, limitType, limitValue, IsShow, IconID) VALUES (76885, N'', N'GG xin hướng dẫn bạn các cách nạp xu như sau:
